-- Phase L: worker crash recovery. Expired leases are requeued until max_attempts, then dead-lettered as failed.
create or replace function public.recover_expired_scheduled_runs(p_limit integer default 50) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.scheduled_runs set status=case when attempt_count+1>=max_attempts then 'failed' else 'queued' end,attempt_count=attempt_count+1,error=case when attempt_count+1>=max_attempts then 'Worker lease expired after maximum attempts' else 'Worker lease expired; run requeued' end,lease_token=null,lease_expires_at=null,started_at=null,updated_at=now() where id in (select id from public.scheduled_runs where status='running' and lease_expires_at is not null and lease_expires_at<now() order by lease_expires_at asc limit greatest(1,least(p_limit,100))); get diagnostics n=row_count; return n; end; $$;
create or replace function public.claim_queued_scheduled_runs(p_limit integer default 10,p_lease_seconds integer default 120) returns setof public.scheduled_runs language plpgsql security definer set search_path=public as $$ declare v_run public.scheduled_runs; begin for v_run in select * from public.scheduled_runs where status='queued' order by scheduled_for asc,created_at asc for update skip locked limit greatest(1,least(p_limit,50)) loop update public.scheduled_runs set status='running',lease_token=gen_random_uuid(),lease_expires_at=now()+make_interval(secs=>greatest(30,least(p_lease_seconds,900))),started_at=now(),updated_at=now() where id=v_run.id returning * into v_run; return next v_run; end loop; return; end; $$;
revoke all on function public.recover_expired_scheduled_runs(integer) from public,anon,authenticated; revoke all on function public.claim_queued_scheduled_runs(integer,integer) from public,anon,authenticated;
